#include <bits/stdc++.h>
using namespace std;

static char ibuf[1 << 16];
static size_t ilen = 0, ipos = 0;

static inline int gc() {
    if (ipos == ilen) {
        ilen = fread(ibuf, 1, sizeof ibuf, stdin);
        ipos = 0;
        if (ilen == 0) return -1;
    }
    return ibuf[ipos++];
}

static long long readInt() {
    int c = gc();
    while (c == ' ' || c == '\n' || c == '\r' || c == '\t') c = gc();
    bool neg = c == '-';
    if (neg) c = gc();
    long long v = 0;
    while (c >= '0' && c <= '9') {
        v = v * 10 + (c - '0');
        c = gc();
    }
    return neg ? -v : v;
}

static string readToken() {
    int c = gc();
    while (c == ' ' || c == '\n' || c == '\r' || c == '\t') c = gc();
    string s;
    while (c > ' ') {
        s.push_back((char)c);
        c = gc();
    }
    return s;
}

int main() {
    string c = readToken(), s = readToken();
    const long long MOD = 1000000007LL;
    int m = (int)s.size();
    // dp[j]: subsequences equal to the first j characters of s; greater: subsequences already greater.
    vector<long long> dp(m + 1, 0);
    dp[0] = 1;
    long long greater = 0;
    for (char ch : c) {
        greater = (greater * 2 + dp[m]) % MOD;
        for (int j = m - 1; j >= 0; j--) {
            if (ch > s[j]) greater = (greater + dp[j]) % MOD;
            else if (ch == s[j]) dp[j + 1] = (dp[j + 1] + dp[j]) % MOD;
        }
    }
    printf("%lld\n", greater);
}

import java.io.*;
import java.util.*;

public class Main {
    static final InputStream IN = System.in;
    static final byte[] BUF = new byte[1 << 16];
    static int len, ptr;

    static int readByte() throws IOException {
        if (ptr == len) {
            len = IN.read(BUF, 0, BUF.length);
            ptr = 0;
            if (len <= 0) {
                len = 0;
                return -1;
            }
        }
        return BUF[ptr++];
    }

    static long nextLong() throws IOException {
        int c = readByte();
        while (c == ' ' || c == '\n' || c == '\r' || c == '\t') c = readByte();
        boolean neg = c == '-';
        if (neg) c = readByte();
        long v = 0;
        while (c >= '0' && c <= '9') {
            v = v * 10 + (c - '0');
            c = readByte();
        }
        return neg ? -v : v;
    }

    static int nextInt() throws IOException {
        return (int) nextLong();
    }

    static String next() throws IOException {
        int c = readByte();
        while (c == ' ' || c == '\n' || c == '\r' || c == '\t') c = readByte();
        StringBuilder sb = new StringBuilder();
        while (c > ' ') {
            sb.append((char) c);
            c = readByte();
        }
        return sb.toString();
    }

    public static void main(String[] args) throws IOException {
        String c = next(), s = next();
        final long MOD = 1000000007L;
        int m = s.length();
        char[] sc = s.toCharArray();
        long[] dp = new long[m + 1];
        dp[0] = 1;
        long greater = 0;
        for (int i = 0; i < c.length(); i++) {
            char ch = c.charAt(i);
            greater = (greater * 2 + dp[m]) % MOD;
            for (int j = m - 1; j >= 0; j--) {
                if (ch > sc[j]) greater = (greater + dp[j]) % MOD;
                else if (ch == sc[j]) dp[j + 1] = (dp[j + 1] + dp[j]) % MOD;
            }
        }
        System.out.println(greater);
    }
}

package main

import (
	"fmt"
	"io"
	"os"
)

var data []byte
var pos int

// token returns the next whitespace-separated token of stdin.
func token() []byte {
	for pos < len(data) && data[pos] <= ' ' {
		pos++
	}
	start := pos
	for pos < len(data) && data[pos] > ' ' {
		pos++
	}
	return data[start:pos]
}

func nextInt() int {
	b := token()
	neg := len(b) > 0 && b[0] == '-'
	if neg {
		b = b[1:]
	}
	v := 0
	for _, c := range b {
		v = v*10 + int(c-'0')
	}
	if neg {
		return -v
	}
	return v
}

func main() {
